{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this packing plan — for example, minimize the number of containers used, minimize total transportation cost, maximize the total weight of goods packed, or something else?"
  ],
  "rationale": "The response asks for a single policy choice (the objective function) and provides examples of that choice, so it is one atomic question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are all available goods required to be packed and shipped, or is it acceptable to leave some units of any goods type unshipped?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding whether all goods must be shipped or if some can be left unshipped."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the number of containers available unlimited, or is there a fixed maximum number of containers that can be used?"
  ],
  "rationale": "The response asks a single clarification question regarding the availability limit of containers."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can the number of units of each goods type loaded into a single container be any non-negative integer, or are there per-container limits on how many units of a given type can go into one container?"
  ],
  "rationale": "The response asks a single clarification question regarding whether container loading is unlimited or subject to specific per-type limits."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The rule says a container with any type A must also contain at least one type C — is this a one-way requirement only (A implies C), or does it also mean a container with type C must contain type A?"
  ],
  "rationale": "The response asks for a single policy clarification regarding the directionality of the constraint between type A and type C."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The minimum of 12 units of type D per container — does this apply to every container that is used, including containers that contain no type A?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation on the scope of a specific constraint."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The weight constraints (at least 18 tons and no more than 60 tons) — do these apply to every container that is used, or only to containers that actually contain goods?"
  ],
  "rationale": "The response asks a single clarification question regarding the scope of the weight constraints."
}

{
  "action": "question",
